// Pure bid arithmetic for a ductless mini-split / heat-pump install.
// No network, no state: every head, foot of line-set, wage, and adder is an
// input, so the result stays a transparent calculation the installer can
// check against their own invoices rather than a claim about what any
// system "should" cost.
//
// The method is the one the trade actually loses money on: a flat per-head
// or per-ton quote treats a first-floor 12k wall-mount with 15 ft of
// line-set and a gravity drain as the same job as a second-story cassette
// with 50 ft of line-set, a condensate pump, and a new 240 V circuit. The
// second one can eat the entire margin of a "$2,800 a head" price.
// Equipment still scales with heads. Line-set extras, height, head type,
// and electrical work do not, and they have to be priced as their own
// hours and material.

// Starting indoor-head labor multipliers. These are ballpark figures to
// start from, NOT an industry standard: real multipliers depend on the
// crew, the wall construction, and how much of the head is actually
// reachable without extra set-up.
export const HEAD_TYPE_PRESETS = Object.freeze([
  { id: 'wall', label: 'High-wall mount (standard)', factor: 1.0 },
  { id: 'floor', label: 'Floor console', factor: 1.1 },
  { id: 'cassette', label: 'Ceiling cassette', factor: 1.35 },
  { id: 'ducted', label: 'Concealed / short-run ducted', factor: 1.5 },
  { id: 'mixed', label: 'Mixed head types (use the harder one)', factor: 1.25 },
]);

// Height multiplies indoor and line-set labor only. The outdoor unit stays
// at grade; a second-story head does not make the pad pour cheaper.
export const STORY_PRESETS = Object.freeze([
  { id: 'first', label: 'First floor / slab, easy access', factor: 1.0 },
  { id: 'second', label: 'Second story', factor: 1.2 },
  { id: 'third', label: 'Third story or higher', factor: 1.45 },
  { id: 'ladder', label: 'Tall first-floor wall, ladder work', factor: 1.15 },
]);

// Electrical extras that a per-head quote almost always forgets. Hours and
// material are starting points; the installer replaces them with their own
// last-job numbers.
export const ELECTRICAL_PRESETS = Object.freeze([
  { id: 'existing', label: 'Existing 240 V disconnect in place', hours: 0, material: 0 },
  { id: 'circuit-20', label: 'New 20–30 A circuit + disconnect + whip', hours: 3.5, material: 280 },
  { id: 'circuit-40', label: 'New 40–50 A circuit + disconnect + whip', hours: 4.5, material: 380 },
  { id: 'subpanel', label: 'New subpanel / feeder for the outdoor', hours: 6, material: 520 },
  { id: 'relocate', label: 'Relocate disconnect or long outdoor whip', hours: 2.5, material: 160 },
]);

export const CONDENSATE_PRESETS = Object.freeze([
  { id: 'gravity', label: 'Gravity drain (short, pitched)', hours: 0, material: 0 },
  { id: 'pump', label: 'Condensate pump (no gravity path)', hours: 1.5, material: 180 },
  { id: 'long-drain', label: 'Long gravity drain or condensate line chase', hours: 2, material: 90 },
]);

export const SYSTEM_PRESETS = Object.freeze([
  {
    label: 'Single-zone 12k wall, first floor',
    headCount: 1,
    btuPerHead: 12000,
    outdoorUnitCost: 1400,
    indoorHeadCostEach: 550,
    branchBoxCost: 0,
    lineSetFeet: 15,
  },
  {
    label: 'Single-zone 18k wall, second story',
    headCount: 1,
    btuPerHead: 18000,
    outdoorUnitCost: 1700,
    indoorHeadCostEach: 620,
    branchBoxCost: 0,
    lineSetFeet: 35,
  },
  {
    label: 'Dual-zone 18k + 12k, first floor',
    headCount: 2,
    btuPerHead: 15000,
    outdoorUnitCost: 2200,
    indoorHeadCostEach: 580,
    branchBoxCost: 350,
    lineSetFeet: 40,
  },
  {
    label: 'Triple-zone, mixed heights',
    headCount: 3,
    btuPerHead: 12000,
    outdoorUnitCost: 2800,
    indoorHeadCostEach: 560,
    branchBoxCost: 420,
    lineSetFeet: 70,
  },
]);

function number(value, name, { min = 0, allowZero = true } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (!allowZero && result === 0) throw new Error(`${name} must be greater than zero`);
  return result;
}

/**
 * Price a mini-split install from heads, line-set extras, head type, story,
 * electrical extras, and the installer's own cost structure.
 *
 * @param {object} input
 * @param {number} input.headCount
 * @param {number} input.btuPerHead          Nominal capacity per indoor head.
 * @param {number} input.outdoorUnitCost
 * @param {number} input.indoorHeadCostEach
 * @param {number} input.branchBoxCost       Multi-zone branch box / headers.
 * @param {number} input.lineSetFeet         Total line-set length, all runs.
 * @param {number} input.includedFeetPerHead Feet the equipment quote includes.
 * @param {number} input.lineSetMaterialPerExtraFoot
 * @param {number} input.hoursPerExtraTenFeet
 * @param {number} input.headTypeFactor      Multiplier on indoor-head labor.
 * @param {number} input.storyFactor         Multiplier on indoor + line-set labor.
 * @param {number} input.indoorHoursPerHead  Mount, flare, drain on an easy wall.
 * @param {number} input.outdoorHours        Pad, mount, whip — not height-scaled.
 * @param {number} input.commissionHoursPerHead  Vacuum, charge, commission.
 * @param {number} input.hourlyWage
 * @param {number} input.burdenRate
 * @param {number} input.electricalHours
 * @param {number} input.electricalMaterial
 * @param {number} input.condensateHours
 * @param {number} input.condensateMaterial
 * @param {number} input.permitFee
 * @param {number} input.travelAndLift
 * @param {number} input.overheadRate
 * @param {number} input.targetMargin
 * @param {number|null} input.proposedPrice
 */
export function calculateBid(input) {
  const headCount = number(input.headCount ?? 0, 'Head count', { allowZero: false });
  const btuPerHead = number(input.btuPerHead ?? 0, 'BTU per head', { allowZero: false });
  const outdoorUnitCost = number(input.outdoorUnitCost ?? 0, 'Outdoor unit cost');
  const indoorHeadCostEach = number(input.indoorHeadCostEach ?? 0, 'Indoor head cost');
  const branchBoxCost = number(input.branchBoxCost ?? 0, 'Branch box cost');
  const lineSetFeet = number(input.lineSetFeet ?? 0, 'Line-set feet');
  const includedFeetPerHead = number(input.includedFeetPerHead ?? 0, 'Included feet per head');
  const lineSetMaterialPerExtraFoot = number(input.lineSetMaterialPerExtraFoot ?? 0, 'Line-set material per extra foot');
  const hoursPerExtraTenFeet = number(input.hoursPerExtraTenFeet ?? 0, 'Hours per extra 10 feet');
  const headTypeFactor = number(input.headTypeFactor ?? 0, 'Head-type factor', { allowZero: false });
  const storyFactor = number(input.storyFactor ?? 0, 'Story factor', { allowZero: false });
  const indoorHoursPerHead = number(input.indoorHoursPerHead ?? 0, 'Indoor hours per head', { allowZero: false });
  const outdoorHours = number(input.outdoorHours ?? 0, 'Outdoor hours');
  const commissionHoursPerHead = number(input.commissionHoursPerHead ?? 0, 'Commission hours per head');
  const hourlyWage = number(input.hourlyWage ?? 0, 'Hourly wage');
  const burdenRate = number(input.burdenRate ?? 0, 'Payroll burden');
  const electricalHours = number(input.electricalHours ?? 0, 'Electrical extra hours');
  const electricalMaterial = number(input.electricalMaterial ?? 0, 'Electrical extra material');
  const condensateHours = number(input.condensateHours ?? 0, 'Condensate hours');
  const condensateMaterial = number(input.condensateMaterial ?? 0, 'Condensate material');
  const permitFee = number(input.permitFee ?? 0, 'Permit fee');
  const travelAndLift = number(input.travelAndLift ?? 0, 'Travel and lift');
  const overheadRate = number(input.overheadRate ?? 0, 'Overhead');
  const targetMargin = number(input.targetMargin ?? 0, 'Target margin');
  if (targetMargin >= 100) throw new Error('Target margin must be less than 100%');

  const totalBtu = headCount * btuPerHead;
  const loadedWage = hourlyWage * (1 + burdenRate / 100);

  // Indoor labor scales with heads, then with head type, then with height.
  // Outdoor labor stays at grade. Line-set extras are the feet beyond what
  // the equipment quote already includes, and those hours climb with the
  // story because a 50 ft run to a second-floor head is not a 50 ft run
  // across a slab.
  const indoorHours = headCount * indoorHoursPerHead * headTypeFactor * storyFactor;
  const includedFeet = includedFeetPerHead * headCount;
  const extraLineSetFeet = Math.max(0, lineSetFeet - includedFeet);
  const lineSetHours = (extraLineSetFeet / 10) * hoursPerExtraTenFeet * storyFactor;
  const lineSetMaterial = extraLineSetFeet * lineSetMaterialPerExtraFoot;
  const commissionHours = headCount * commissionHoursPerHead;
  const totalHours = indoorHours + outdoorHours + lineSetHours + electricalHours + condensateHours + commissionHours;
  const laborCost = totalHours * loadedWage;

  const indoorEquipment = headCount * indoorHeadCostEach;
  const equipmentCost = outdoorUnitCost + indoorEquipment + branchBoxCost;
  const extraMaterial = electricalMaterial + condensateMaterial + lineSetMaterial;
  const softCost = permitFee + travelAndLift;

  const directCost = laborCost + equipmentCost + extraMaterial + softCost;
  const overhead = directCost * overheadRate / 100;
  const totalCost = directCost + overhead;
  const price = totalCost / (1 - targetMargin / 100);
  const profit = price - totalCost;

  const hasProposed = input.proposedPrice !== null && input.proposedPrice !== undefined && input.proposedPrice !== '';
  const proposedPrice = hasProposed ? number(input.proposedPrice, 'Price you are considering') : null;

  const costShare = (amount) => (totalCost === 0 ? 0 : amount / totalCost * 100);

  return {
    headCount,
    btuPerHead,
    totalBtu,
    loadedWage,
    headTypeFactor,
    storyFactor,
    indoorHours,
    outdoorHours,
    extraLineSetFeet,
    lineSetHours,
    lineSetMaterial,
    electricalHours,
    condensateHours,
    commissionHours,
    totalHours,
    laborCost,
    outdoorUnitCost,
    indoorEquipment,
    branchBoxCost,
    equipmentCost,
    electricalMaterial,
    condensateMaterial,
    extraMaterial,
    permitFee,
    travelAndLift,
    softCost,
    overhead,
    directCost,
    totalCost,
    price,
    profit,
    pricePerHead: price / headCount,
    costPerHead: totalCost / headCount,
    pricePerKbtu: totalBtu === 0 ? null : price / (totalBtu / 1000),
    effectiveHourlyRate: totalHours === 0 ? null : price / totalHours,
    breakEvenPrice: totalCost,
    breakEvenPerHead: totalCost / headCount,
    shares: {
      labor: costShare(laborCost),
      equipment: costShare(equipmentCost),
      extras: costShare(extraMaterial),
      soft: costShare(softCost),
      overhead: costShare(overhead),
    },
    proposed: proposedPrice === null ? null : {
      price: proposedPrice,
      profit: proposedPrice - totalCost,
      margin: proposedPrice === 0 ? 0 : (proposedPrice - totalCost) / proposedPrice * 100,
      perHead: proposedPrice / headCount,
      hourlyRate: totalHours === 0 ? null : proposedPrice / totalHours,
      belowBreakEven: proposedPrice < totalCost,
    },
  };
}

/**
 * Format a bid as a plain-text draft the installer can paste into a proposal.
 * Costs and wages are omitted on purpose — this is the customer-facing side.
 */
export function formatBidSummary(result) {
  const money = (value) => {
    const format = (value) => `$${value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    const text = format(Math.abs(value));
    return value < 0 && /[1-9]/.test(text) ? `-${text}` : text;
  };
  const kbtu = (result.totalBtu / 1000).toFixed(1);
  return [
    'MINI-SPLIT / DUCTLESS INSTALL BID',
    '',
    `Proposed install price: ${money(result.price)}`,
    `System: ${result.headCount} indoor head${result.headCount === 1 ? '' : 's'}, ${kbtu} kBTU total`,
    `Price per head: ${money(result.pricePerHead)}`,
    `Install labor: ${result.totalHours.toFixed(1)} crew-hours`,
    '',
    'SCOPE BASIS',
    `- Indoor type factor ${result.headTypeFactor.toFixed(2)}, story factor ${result.storyFactor.toFixed(2)}`,
    `- Extra line-set: ${result.extraLineSetFeet.toFixed(1)} ft beyond included length`,
    `- Electrical extra: ${result.electricalHours.toFixed(1)} h`,
    result.condensateHours > 0 || result.condensateMaterial > 0
      ? `- Condensate: ${result.condensateHours.toFixed(1)} h`
      : null,
    '',
    'This is a draft for review. Confirm equipment selection, line-set path, electrical and condensate scope, permits, refrigerant handling, and all pricing before sending.',
  ].filter((line) => line !== null).join('\n');
}

proposal.mjs.text:
// Turns a finished bid into the document the contractor actually hands the
// customer: a one-page proposal they can print or "Save as PDF" from the
// browser.
//
// Why this exists
// ---------------
// Every bid calculator in this portfolio already ends at a number and a
// plain-text blurb to paste somewhere. That is where the tool stops and the
// contractor's evening starts: retyping the scope into Word, remembering the
// deposit split, guessing how long the price should stand. The proposal is the
// thing that wins or loses the job, and it was the one artifact none of these
// tools produced.
//
// Deliberately NOT a contract
// ---------------------------
// This renders the contractor's own words and numbers into a tidy layout. It
// invents no legal terms, warranties, lien language, or cancellation rights —
// every clause on the page is text the user typed or left blank. A "proposal"
// that shipped boilerplate terms drafted by a calculator would be exactly the
// legal exposure `PRODUCT_PLAYBOOK.md` §5b tells us to avoid, and it would be
// wrong in most jurisdictions anyway.
//
// Privacy
// -------
// `loadCompany` / `saveCompany` persist the *contractor's own* business block
// (their name, phone, licence) so they type it once. The customer's name and
// address are never persisted: that is a third party's personal data sitting on
// someone else's device, and re-typing it per job is cheap. Nothing here
// touches the network.
//
// This file is generic on purpose — no trade, no venture, no storage key baked
// in — so it can be copied verbatim into any calculator in `ventures/`. See the
// venture README for the wiring steps.

/** Fields of the contractor's own business block, in display order. */
export const COMPANY_FIELDS = Object.freeze([
  'companyName', 'companyPhone', 'companyEmail', 'companyLicense', 'companyAddress',
]);

/** Fields describing the customer and the job. Never persisted. */
export const CLIENT_FIELDS = Object.freeze([
  'clientName', 'clientAddress',
]);

/** Commercial terms the contractor controls. */
export const TERM_FIELDS = Object.freeze([
  'depositPercent', 'validDays', 'paymentTerms', 'proposalNotes', 'proposalExclusions',
]);

export function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function text(value) {
  return String(value ?? '').trim();
}

function number(value, name, { min = 0, max = Infinity } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (result > max) throw new Error(`${name} must be at most ${max}`);
  return result;
}

/**
 * A figure for the customer's copy.
 *
 * `currency` defaults to `'$'`, which is what every trade in this portfolio
 * quotes in and what all 102 adopters rendered before it was a parameter — so
 * an unchanged caller gets a byte-identical document.
 *
 * It exists because the document is not only a US construction bid. A
 * freelancer quoting a translation names their own currency on the page, and
 * printing `$1,200.00` on a quote the client will pay in euros is not a display
 * nicety: it misstates the price on the one sheet that is meant to settle it.
 * The venture passes whatever its own currency field says.
 *
 * A label is spaced from the figure and a symbol is not — `USD 1,200.00` but
 * `$1,200.00` and `€1,200.00` — decided by whether the currency ends in a
 * letter, which is the only difference a reader would notice between the two.
 *
 * That space is a non-breaking one, written as an escape so it cannot be
 * mistaken for an ordinary space by anyone reading this file or matching
 * against its output. A quote is a printed document with a narrow price
 * column, and "USD" left stranded at the end of a line with its figure on the
 * next is the one place this layout can break in a way the customer sees.
 */
export function money(value, currency = '$') {
  // Sign goes outside the currency symbol: "-$9.24", not "$-9.24". The old
  // spelling put it inside, which is what interpolating a negative straight
  // after a "$" gets you, and it reads as a typo on a document a contractor
  // hands a customer.
  //
  // Round to cents *before* choosing the sign. A delta of two equal figures
  // lands on -0, and a residual like -0.004 rounds to zero at cent precision;
  // both used to print "$-0.00" — a line that is exactly break-even claiming
  // to be down money.
  const cents = Math.round(Math.abs(value) * 100);
  const sign = cents === 0 ? '' : value < 0 ? '-' : '';
  const amount = (cents / 100).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  const unit = text(currency) || '$';
  return `${sign}${unit}${/[A-Za-z]$/.test(unit) ? '\u00a0' : ''}${amount}`;
}

/**
 * Split a textarea into trimmed, non-empty lines. Blank lines are how people
 * space out a scope list; they should not become empty bullets.
 */
export function lines(value) {
  return text(value)
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);
}

/**
 * Fill scope templates from a calculator's result, dropping any line whose
 * figures are not there.
 *
 * Every adoption batch so far has lost a line to the same defect: each
 * calculator names its result differently, `result.doorClass` or `run.material`
 * resolves to `undefined` rather than throwing, and the customer's scope reads
 * "undefined ft of undefined" while every suite stays green. Guessing is the
 * problem; this makes guessing wrong *visible* instead of silent.
 *
 * A template is `'Install {totalLinearFeet} ft of {fenceName}'`, or an object
 * `{ line, when }` where `when` names a field that must be truthy for the line
 * to appear at all.
 *
 * `{ each, line, when }` renders one line **per element** of the array at
 * `each`, with `{field}` reading that element rather than the result root.
 * Half the calculators here price an itemised job — rooms of flooring, gutter
 * runs, trees, kitchen exhaust components — and a homeowner collecting three
 * bids compares the line items, not a total. Without this the only scope such
 * a trade could draft is "Perform the work described above", which the README
 * is explicit is worth less than no proposal at all. `when` is read against
 * the element too, so a row the contractor left at zero stays off the quote:
 *
 * ```json
 * { "each": "rooms", "when": "hours", "line": "{name} — {squareFeet~0} sq ft" }
 * ```
 *
 * Elements are not truncated. Every row the contractor entered is a row they
 * intend to be paid for, and "…and 4 more" on a document someone signs is a
 * dispute waiting to happen.
 *
 * `{field+s}` is that field's plural suffix — `'s'` unless the value is exactly
 * one — so `'{gates} gate{gates+s}'` reads "1 gate" and "3 gates". Without it
 * the obvious thing to write is `'{gates} gate{gates}'`, which prints
 * "3 gate3" on a customer's quote.
 *
 * `{field~2}` rounds to that many decimals and groups thousands, so a derived
 * figure reads "48.89 yd²" and "1,600 sq ft" rather than "48.888888888888886"
 * and "1600". Anything computed — a yardage, a tonnage, a square count — needs
 * it: a quote carrying fifteen decimal places tells the customer the number was
 * produced by a machine that was not being watched.
 *
 * A placeholder that resolves to `undefined`, `null`, `''`,
 * `NaN`, or `Infinity` drops its whole line — a scope with one line missing is
 * a scope the contractor edits, whereas a scope reading `undefined` is one they
 * hand to a customer without noticing.
 *
 * Dropping is not the safety property on its own: an empty scope is also wrong,
 * and `platform/proposal/verify.mjs` fails a page whose default scope comes out
 * empty. Between them, a mis-named field cannot reach a customer quietly.
 *
 * @param {Array<string|{line: string, when?: string, each?: string}>} templates
 * @param {object} values The calculator's result (and anything else to read).
 * @returns {string[]}
 */
export function scopeLines(templates, values) {
  const missing = (value) => value === undefined || value === null || value === ''
    || (typeof value === 'number' && !Number.isFinite(value));

  const readFrom = (scope, path) => String(path).split('.')
    .reduce((node, key) => (node === null || node === undefined ? undefined : node[key]), scope);

  /**
   * One template line against one scope, or `null` if any placeholder in it is
   * missing. Shared by plain lines and `each` rows on purpose: a row must drop
   * on a missing figure by exactly the same rule as a top-level line, or the
   * word "undefined" reaches the customer through whichever path was written
   * second.
   */
  const render = (line, scope) => {
    let complete = true;
    const rendered = line.replace(
      /\{([A-Za-z0-9_.]+?)(?:\+([A-Za-z]+)|~(\d))?\}/g,
      (_match, path, plural, decimals) => {
        const value = readFrom(scope, path);
        if (missing(value)) { complete = false; return ''; }
        if (plural !== undefined) return Number(value) === 1 ? '' : plural;
        if (decimals !== undefined) {
          const number = Number(value);
          if (!Number.isFinite(number)) { complete = false; return ''; }
          return number.toLocaleString('en-US', {
            minimumFractionDigits: 0,
            maximumFractionDigits: Number(decimals),
          });
        }
        return String(value);
      },
    );
    return complete && rendered.trim() ? rendered.trim() : null;
  };

  const filled = [];
  for (const template of templates ?? []) {
    const line = typeof template === 'string' ? template : template?.line;
    if (typeof line !== 'string') continue;
    const each = typeof template === 'object' ? template.each : undefined;

    if (each !== undefined) {
      const rows = readFrom(values, each);
      if (!Array.isArray(rows)) continue;
      for (const row of rows) {
        if (row === null || typeof row !== 'object') continue;
        if (template.when !== undefined && !readFrom(row, template.when)) continue;
        const rendered = render(line, row);
        if (rendered !== null) filled.push(rendered);
      }
      continue;
    }

    if (typeof template === 'object' && template.when !== undefined && !readFrom(values, template.when)) continue;
    const rendered = render(line, values);
    if (rendered !== null) filled.push(rendered);
  }
  return filled;
}

/**
 * `YYYY-MM-DD` plus a whole number of days, in UTC.
 *
 * Local-time date arithmetic silently shifts by a day across a DST boundary,
 * which on a quote-expiry date is a real dispute with a customer.
 */
export function addDays(isoDate, days) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text(isoDate));
  if (!match) throw new Error('Issue date must be YYYY-MM-DD');
  const [, year, month, day] = match;
  const stamp = Date.UTC(Number(year), Number(month) - 1, Number(day));
  if (Number.isNaN(stamp)) throw new Error('Issue date must be a real date');
  return new Date(stamp + number(days, 'Valid days') * 86_400_000)
    .toISOString()
    .slice(0, 10);
}

/** `2026-08-26` → `26 August 2026`. Unambiguous to both US and non-US readers. */
export function formatDate(isoDate) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text(isoDate));
  if (!match) return text(isoDate);
  const [, year, month, day] = match;
  const monthName = new Date(Date.UTC(Number(year), Number(month) - 1, 1))
    .toLocaleDateString('en-US', { month: 'long', timeZone: 'UTC' });
  return `${Number(day)} ${monthName} ${year}`;
}

/**
 * A short, stable reference the contractor and the customer can both quote on
 * the phone. Derived from the issue date and the customer name so that
 * re-printing the same proposal gives the same number, and two proposals
 * written the same day for different customers do not collide.
 */
export function referenceFor(issuedOn, clientName) {
  const compact = text(issuedOn).replaceAll('-', '');
  let hash = 0;
  for (const character of text(clientName).toUpperCase()) {
    hash = (hash * 31 + character.codePointAt(0)) % 1_048_576;
  }
  return `Q-${compact}-${hash.toString(36).toUpperCase().padStart(4, '0').slice(-4)}`;
}

/**
 * Assemble and validate a proposal.
 *
 * Throws on the things that would embarrass the contractor in front of a
 * customer — no business name, no customer name, a zero price, a deposit over
 * 100% — rather than rendering a document with a hole in it.
 */
export function buildProposal(input = {}) {
  const companyName = text(input.companyName);
  if (!companyName) throw new Error('Add your business name before printing a proposal');
  const clientName = text(input.clientName);
  if (!clientName) throw new Error('Add the customer name before printing a proposal');

  const price = number(input.price, 'Price', { min: 0 });
  if (price <= 0) throw new Error('Price a job before printing a proposal');

  const depositPercent = number(input.depositPercent ?? 0, 'Deposit', { min: 0, max: 100 });
  const validDays = number(input.validDays ?? 0, 'Valid days', { min: 0, max: 3650 });
  const issuedOn = text(input.issuedOn) || new Date().toISOString().slice(0, 10);

  // Rounded to cents here, not at display time, and the balance taken as the
  // remainder. The customer adds the two lines up: if the deposit rounds up and
  // the balance rounds down independently, the printed figures miss the printed
  // total by a cent, and the contractor has to explain it on the phone.
  const depositAmount = Math.round(price * depositPercent) / 100;

  return {
    reference: referenceFor(issuedOn, clientName),
    issuedOn,
    validDays,
    validUntil: validDays === 0 ? null : addDays(issuedOn, validDays),
    company: {
      name: companyName,
      phone: text(input.companyPhone),
      email: text(input.companyEmail),
      license: text(input.companyLicense),
      address: text(input.companyAddress),
    },
    client: {
      name: clientName,
      address: text(input.clientAddress),
    },
    job: {
      title: text(input.jobTitle) || 'Proposed work',
      scope: lines(input.scope),
      exclusions: lines(input.proposalExclusions),
      notes: text(input.proposalNotes),
    },
    pricing: {
      price,
      depositPercent,
      depositAmount,
      balanceAmount: price - depositAmount,
      paymentTerms: text(input.paymentTerms),
    },
  };
}

function block(title, body) {
  return body ? `<div class="pr-block"><h3>${escapeHtml(title)}</h3>${body}</div>` : '';
}

function list(items) {
  return items.length === 0
    ? ''
    : `<ul>${items.map((item) => `<li>${escapeHtml(item)}</li>`).join('')}</ul>`;
}

function paragraphs(value) {
  return value ? `<p>${escapeHtml(value).replaceAll('\n', '<br>')}</p>` : '';
}

/**
 * Render the proposal as the HTML that goes inside the page's print container.
 *
 * Returns a fragment, not a whole document: the page owns the print stylesheet,
 * so the same markup is what the contractor previews on screen and what comes
 * out of the printer. A separate print-only document is how the two drift.
 *
 * @param {ReturnType<typeof buildProposal>} proposal
 * @param {object} [options]
 * @param {string} [options.disclaimer] Sentence to print in the footer. The
 *   caller supplies it so each trade can name its own regulator and scope.
 * @param {string} [options.currency] Prefix for every figure on the sheet.
 *   Defaults to `'$'`; see `money`.
 */
export function renderProposalHtml(proposal, { disclaimer = '', currency = '$' } = {}) {
  const { company, client, job, pricing } = proposal;
  const amount = (value) => money(value, currency);

  const contact = [company.phone, company.email, company.address]
    .filter(Boolean)
    .map((line) => `<span>${escapeHtml(line)}</span>`)
    .join('');

  const validity = proposal.validUntil
    ? `<p class="pr-validity">This price is held until <strong>${escapeHtml(formatDate(proposal.validUntil))}</strong> (${proposal.validDays} days from issue).</p>`
    : '';

  const depositRow = pricing.depositPercent > 0
    ? `<tr><td>Deposit due on acceptance (${pricing.depositPercent}%)</td><td>${amount(pricing.depositAmount)}</td></tr>
       <tr><td>Balance due on completion</td><td>${amount(pricing.balanceAmount)}</td></tr>`
    : '';

  return `
    <article class="pr-doc">
      <header class="pr-head">
        <div>
          <h2>${escapeHtml(company.name)}</h2>
          <div class="pr-contact">${contact}</div>
          ${company.license ? `<p class="pr-license">Licence ${escapeHtml(company.license)}</p>` : ''}
        </div>
        <div class="pr-meta">
          <p class="pr-kicker">Proposal</p>
          <p><strong>${escapeHtml(proposal.reference)}</strong></p>
          <p>${escapeHtml(formatDate(proposal.issuedOn))}</p>
        </div>
      </header>

      <div class="pr-parties">
        <div class="pr-block"><h3>Prepared for</h3>
          <p><strong>${escapeHtml(client.name)}</strong></p>
          ${paragraphs(client.address)}
        </div>
        <div class="pr-block"><h3>Work</h3>
          <p><strong>${escapeHtml(job.title)}</strong></p>
        </div>
      </div>

      ${block('Scope of work', list(job.scope))}
      ${block('Not included', list(job.exclusions))}
      ${block('Notes', paragraphs(job.notes))}

      <table class="pr-price">
        <tbody>
          <tr class="pr-total"><td>Total price</td><td>${amount(pricing.price)}</td></tr>
          ${depositRow}
        </tbody>
      </table>
      ${validity}
      ${block('Payment terms', paragraphs(pricing.paymentTerms))}

      <div class="pr-sign">
        <div><span class="pr-rule"></span><p>Customer signature</p></div>
        <div><span class="pr-rule"></span><p>Date</p></div>
      </div>

      ${disclaimer ? `<p class="pr-disclaimer">${escapeHtml(disclaimer)}</p>` : ''}
    </article>
  `;
}

/**
 * Read the saved business block. A corrupt or absent entry is an empty block,
 * never an exception: a broken localStorage value must not stop someone
 * pricing a job.
 */
export function loadCompany(storage, key) {
  try {
    const saved = JSON.parse(storage?.getItem(key) || '{}');
    return Object.fromEntries(
      COMPANY_FIELDS.map((field) => [field, text(saved?.[field])]),
    );
  } catch {
    return Object.fromEntries(COMPANY_FIELDS.map((field) => [field, '']));
  }
}

/**
 * Persist the business block only. `CLIENT_FIELDS` are excluded by
 * construction, not by the caller remembering to strip them.
 */
export function saveCompany(storage, key, values = {}) {
  const payload = Object.fromEntries(
    COMPANY_FIELDS.map((field) => [field, text(values[field])]),
  );
  try {
    storage?.setItem(key, JSON.stringify(payload));
  } catch {
    // A full or disabled localStorage is not worth an error in front of the
    // customer; the proposal still prints, it just will not be pre-filled next
    // time.
  }
  return payload;
}

export function forgetCompany(storage, key) {
  try {
    storage?.removeItem(key);
  } catch {
    // Same reasoning as saveCompany.
  }
}

share.mjs.text:
// A setter re-enters the same wage, burden, overhead, markup, and material
// rates on every single bid. Losing them when the tab closes is the reason a
// pricing tool gets used once and never again, so this module keeps the whole
// form: to the visitor's own browser between visits, and into a link they can
// send themselves, a partner, or the customer.
//
// The transform is pure and takes the field spec as an argument rather than
// keeping its own copy of the field list. That is deliberate. `index.html`
// already declares the ids `readInput()` reads, so passing those same arrays
// in means a field added to the form is shareable the moment it exists. A
// second hand-maintained allowlist in here would silently drop whatever the
// form grew since — a shared link that computes a different price than the
// sender saw is worse than no link at all.
//
// Nothing here is transmitted. `localStorage` is the visitor's own disk, and
// the link is only ever built in their browser and copied by them. The bid
// travels in the URL *fragment* (`#...`), never the query string: a fragment
// is not sent in the request line a server logs, nor in the `Referer` header a
// later click would carry, so the numbers a setter typed stay on the machines
// they choose to send the link to. `encodeBid` returns a bare parameter string
// and `decodeBid` accepts it with or without a leading `#`, so this module
// stays agnostic to which the caller uses; the calculators use the fragment.

// Spec shape, built by the caller from its existing id lists:
//   {
//     key:     'kitchen-tile-backsplash-bid',   // localStorage key
//     numbers: ['wallSf', 'hourlyWage', ...],   // free numeric inputs
//     flags:   ['includeCooktop', ...],         // checkboxes
//     choices: { scope: ['tile-only', ...] },   // selects, with their options
//     text:    ['paymentTerms', ...],           // free prose (textarea)
//     rows:    { param: 'a', fields: [...] },   // optional repeated group
//   }
//
// `rows` is for a form whose shape the visitor sets — the janitorial bid is a
// list of spaces in a building, and there is no fixed field list to name. It
// is the case that most needs keeping: re-measuring a building to re-price it
// is an hour of work, not a retyped wage. Each row encodes as colon-separated
// values in spec order, rows separated by commas, under one parameter.

const VERSION = 1;
const ROW_SEPARATOR = ',';
const CELL_SEPARATOR = ':';
// A form the visitor grows without limit is a form a crafted link can grow
// without limit too. This is far above any real building and far below what
// would take a browser down.
const MAX_ROWS = 200;

// Only a finite, non-negative number is carried. That is the same contract the
// calculators enforce on input, so a restored or shared value can never
// prefill a field the calculator would then reject.
function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  const result = Number(value);
  if (!Number.isFinite(result) || result < 0) return null;
  return result;
}

function specNumbers(spec) {
  return Array.isArray(spec?.numbers) ? spec.numbers : [];
}

function specFlags(spec) {
  return Array.isArray(spec?.flags) ? spec.flags : [];
}

function specChoices(spec) {
  return spec?.choices && typeof spec.choices === 'object' ? spec.choices : {};
}

function specText(spec) {
  return Array.isArray(spec?.text) ? spec.text : [];
}

// The proposal panel's terms — see `withProposalTerms`. Two numbers and three
// blocks of prose, named here rather than in the page because the page's copy
// of the list is generated by `platform/proposal/adopt.mjs` and a second
// hand-kept copy beside it is the exact defect this module's header warns
// about. `platform/proposal/term-ids.test.mjs` asserts the two agree.
export const PROPOSAL_TERM_NUMBERS = Object.freeze(['depositPercent', 'validDays']);
export const PROPOSAL_TERM_TEXT = Object.freeze([
  'proposalExclusions', 'paymentTerms', 'proposalNotes',
]);

// A ceiling on one block of prose, matching `MAX_LINK_VALUE` in
// `platform/pages/link.mjs` so the two share mechanisms on this site agree
// about what fits in a fragment. Payment terms and exclusions are a sentence or
// two in every real bid; a field past this is a document, and a URL is not
// where a document travels.
export const MAX_TERM_TEXT = 512;

// Prose is carried as typed, newlines included — these are textareas and a
// three-line exclusions list is three lines on the customer's sheet. Only two
// things are taken out: the control characters no textarea produces and no
// proposal should render, and the surrounding whitespace, so a field holding
// only a stray newline reads as empty rather than as terms the sender wrote.
//
// Over-long is `null` — dropped, not truncated. Half a payment-terms clause,
// presented to the recipient as the sender's terms, is worse than the field
// arriving empty, and `overlongTerms` is what lets the sender be told which one
// stayed behind instead of finding out from the customer.
function usableText(value) {
  if (typeof value !== 'string') return null;
  // eslint-disable-next-line no-control-regex
  const clean = value.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim();
  if (!clean) return null;
  return clean.length > MAX_TERM_TEXT ? null : clean;
}

/**
 * The spec, plus the proposal terms this page also puts in front of the setter.
 *
 * Why this is not simply written into each venture's spec: the terms are not
 * the venture's fields. They arrive with the proposal panel that
 * `platform/proposal/adopt.mjs` generates into the page, below the pricing form
 * and after the spec is built, so a page cannot name them in its own
 * `numbers`/`text` arrays without restating a list it does not own.
 *
 * The defect this fixes is small on screen and expensive on paper. A setter
 * prices a job at a 50% deposit held for 15 days, sends the link, and the
 * recipient's page opens the *bid* correctly under this venture's defaults —
 * 30% and 30 days. Both people are looking at the same price and different
 * money on acceptance, and nothing anywhere says so. The same was true of the
 * setter's own saved bid on their next visit.
 *
 * Idempotent: folding the terms in twice leaves one copy, so a caller that
 * wraps at every call site (which is what the pages do) cannot grow the spec.
 */
export function withProposalTerms(spec) {
  if (!spec || typeof spec !== 'object') return spec;
  const numbers = specNumbers(spec);
  const text = specText(spec);
  return {
    ...spec,
    numbers: [...numbers, ...PROPOSAL_TERM_NUMBERS.filter((id) => !numbers.includes(id))],
    text: [...text, ...PROPOSAL_TERM_TEXT.filter((id) => !text.includes(id))],
  };
}

/**
 * The form's values, plus whichever term fields this page actually has.
 *
 * `lookup` is the page's own `el` — id to element, or null. Kept as an argument
 * rather than reaching for `document` so this module stays testable without a
 * DOM, which is the whole reason the transform above is pure.
 *
 * A page that has not adopted the proposal panel has no such elements and gets
 * its values back unchanged, so the same call site is correct on every venture
 * whether or not the terms are there.
 */
export function readProposalTerms(values, lookup) {
  const out = { ...(values || {}) };
  if (typeof lookup !== 'function') return out;
  for (const id of [...PROPOSAL_TERM_NUMBERS, ...PROPOSAL_TERM_TEXT]) {
    let field = null;
    try {
      field = lookup(id);
    } catch {
      // `el` throws on some pages when the id is absent. Absent is the answer.
    }
    if (field && typeof field.value === 'string') out[id] = field.value;
  }
  return out;
}

/**
 * Which term fields are too long to ride in a link.
 *
 * Named for the sender at the moment they copy, for the reason
 * `platform/pages/link.mjs` learned on `security-camera-bid-calculator`: a
 * field the encoder set aside silently is a field the recipient reads as one
 * the sender left blank.
 */
export function overlongTerms(values) {
  return PROPOSAL_TERM_TEXT.filter((id) => {
    const raw = values?.[id];
    return typeof raw === 'string' && raw.trim().length > MAX_TERM_TEXT;
  });
}

// What the setter calls these fields. The label on the panel, not the id: a
// status line reading "your proposalExclusions is too long" tells a contractor
// nothing about which box on their screen to shorten.
const TERM_LABELS = Object.freeze({
  proposalExclusions: 'not-included list',
  paymentTerms: 'payment terms',
  proposalNotes: 'notes',
});

/**
 * The sentence a page shows when a term did not fit, or `''` when all of them
 * did.
 *
 * Assembled here rather than in each page for the reason the ids are named
 * here: this wording ships on every calculator that has adopted the proposal,
 * and the alternative is the same sentence written 36 times and corrected in
 * one of them.
 */
export function overlongTermsNote(values) {
  const left = overlongTerms(values).map((id) => TERM_LABELS[id] ?? id);
  if (left.length === 0) return '';
  const named = left.length === 1
    ? left[0]
    : `${left.slice(0, -1).join(', ')} and ${left[left.length - 1]}`;
  return `your ${named} ${left.length === 1 ? 'is' : 'are'} too long to fit in a link `
    + `and stayed behind — send ${left.length === 1 ? 'it' : 'them'} separately if the wording matters`;
}

// A select's value is a string in the DOM, so this used to test `typeof value
// === 'string'` and be done. A page is free to coerce it before handing the
// values here, and one does: `sewer-line-replace-bid-calculator` runs
// `values.diameterIn = Number(values.diameterIn)` in `readInput()` so its own
// arithmetic gets a number. The strict check then dropped `diameterIn` from
// the link *and* from the save, with nothing said — a bid priced for a 6-inch
// lateral reopened as a 4-inch one, for the recipient and for the setter's own
// next visit, and the price moved with it.
//
// So the comparison is made on the string form. The allowed list is still what
// decides: a number that is not an option the select offers is rejected exactly
// as a string that is not. Only a string or a finite number gets that far —
// `true` must not slip in as the option `"true"`, and an object must not
// arrive as `"[object Object]"`.
function choiceText(value) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  return null;
}

// values object -> query string (no leading '?'). Field order follows the
// spec, so the same bid always encodes to the same string and a copied link
// stays stable across visits.
export function encodeBid(spec, values) {
  const params = new URLSearchParams();
  const choices = specChoices(spec);
  for (const [id, allowed] of Object.entries(choices)) {
    const value = choiceText(values?.[id]);
    if (value !== null && allowed.includes(value)) params.set(id, value);
  }
  for (const id of specNumbers(spec)) {
    const value = usableNumber(values?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  for (const id of specFlags(spec)) {
    if (values?.[id] === undefined) continue;
    params.set(id, values[id] ? '1' : '0');
  }
  for (const id of specText(spec)) {
    const value = usableText(values?.[id]);
    if (value !== null) params.set(id, value);
  }
  for (const rows of specRowGroups(spec)) {
    if (!Array.isArray(values?.[rows.param])) continue;
    const encoded = values[rows.param]
      .slice(0, MAX_ROWS)
      .map(row => rows.fields.map(field => encodeCell(field, row?.[field.key])).join(CELL_SEPARATOR))
      // A row where every cell was rejected carries nothing; emitting it would
      // give the recipient a blank space to puzzle over.
      .filter(row => row.replaceAll(CELL_SEPARATOR, '') !== '');
    if (encoded.length > 0) params.set(rows.param, encoded.join(ROW_SEPARATOR));
  }
  return params.toString();
}

function specRows(spec) {
  const rows = spec?.rows;
  if (!rows || typeof rows.param !== 'string' || !Array.isArray(rows.fields)) return null;
  return rows;
}

function specRowGroups(spec) {
  const groups = [];
  const primary = specRows(spec);
  if (primary) groups.push(primary);
  if (Array.isArray(spec?.extraRows)) {
    for (const rows of spec.extraRows) {
      if (rows && typeof rows.param === 'string' && Array.isArray(rows.fields)) {
        groups.push(rows);
      }
    }
  }
  return groups;
}

const MAX_TEXT = 80;

function encodeText(value) {
  const raw = String(value ?? '').trim().slice(0, MAX_TEXT);
  if (!raw) return '';
  // URI-encode so a typed name can contain ":" or "," without splitting the row.
  return encodeURIComponent(raw);
}

function decodeText(raw) {
  if (!raw) return null;
  try {
    const text = decodeURIComponent(raw).trim().slice(0, MAX_TEXT);
    return text || null;
  } catch {
    return null;
  }
}

function encodeCell(field, value) {
  if (field.kind === 'choice') {
    // Same coercion tolerance as `encodeBid` above, for the same reason: a row
    // cell is read out of a form the visitor grew, and a page that normalises
    // it on the way in should not lose it on the way out.
    const text = choiceText(value);
    return text !== null && field.options.includes(text) ? text : '';
  }
  if (field.kind === 'text') return encodeText(value);
  const number = usableNumber(value);
  return number === null ? '' : String(number);
}

function decodeCell(field, raw) {
  if (field.kind === 'choice') return field.options.includes(raw) ? raw : null;
  if (field.kind === 'text') return decodeText(raw);
  const number = usableNumber(raw);
  return number === null ? null : String(number);
}

// query string -> values object. Accepts a bare query string or one with a
// leading '?' or '#', so a caller can hand it `location.search` untouched.
// Only ids named in the spec survive, numbers must parse, and a select only
// takes a value the select actually offers — a crafted link cannot inject a
// scope the calculator has no rates for, or any markup at all.
export function decodeBid(spec, source) {
  if (typeof source !== 'string') return {};
  const params = new URLSearchParams(source.replace(/^[?#]/, ''));
  const values = {};
  for (const [id, allowed] of Object.entries(specChoices(spec))) {
    if (!params.has(id)) continue;
    const value = params.get(id);
    if (allowed.includes(value)) values[id] = value;
  }
  for (const id of specNumbers(spec)) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) values[id] = String(value);
  }
  for (const id of specFlags(spec)) {
    if (!params.has(id)) continue;
    values[id] = params.get(id) === '1';
  }
  // Re-validated on the way in exactly as on the way out, because the fragment
  // is the one part of this page a stranger can write. A crafted link cannot
  // paste a megabyte of prose, or a control character, into a document the
  // contractor is about to print for a customer.
  for (const id of specText(spec)) {
    if (!params.has(id)) continue;
    const value = usableText(params.get(id));
    if (value !== null) values[id] = value;
  }
  for (const rows of specRowGroups(spec)) {
    if (!params.has(rows.param)) continue;
    const decoded = params.get(rows.param)
      .split(ROW_SEPARATOR)
      .slice(0, MAX_ROWS)
      .map(row => {
        const cells = row.split(CELL_SEPARATOR);
        const out = {};
        rows.fields.forEach((field, index) => {
          const value = decodeCell(field, cells[index] ?? '');
          if (value !== null) out[field.key] = value;
        });
        return out;
      })
      // A row that survived validation with nothing in it is not a space the
      // sender described, so it is dropped rather than added to the form.
      .filter(row => Object.keys(row).length > 0);
    if (decoded.length > 0) values[rows.param] = decoded;
  }
  return values;
}

// Writes the bid to the visitor's own storage. Wrapped because a browser with
// site data blocked throws on access rather than returning null, and a setter
// mid-bid should not lose the page over a storage setting.
export function saveBid(storage, spec, values) {
  if (!storage || !spec?.key) return false;
  try {
    storage.setItem(spec.key, JSON.stringify({ v: VERSION, values: decodeBid(spec, encodeBid(spec, values)) }));
    return true;
  } catch {
    return false;
  }
}

// Reads a previously saved bid back, re-validated through the same spec so a
// stored blob edited by hand, or written by an older version of the form, can
// only ever produce fields this build knows about.
export function loadBid(storage, spec) {
  if (!storage || !spec?.key) return {};
  try {
    const raw = storage.getItem(spec.key);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (!parsed || parsed.v !== VERSION || typeof parsed.values !== 'object') return {};
    return decodeBid(spec, encodeBid(spec, parsed.values));
  } catch {
    return {};
  }
}

export function clearBid(storage, spec) {
  if (!storage || !spec?.key) return false;
  try {
    storage.removeItem(spec.key);
    return true;
  } catch {
    return false;
  }
}

// A link wins over storage: a setter who opens a bid someone sent them means
// to see that bid, not the one they last priced. Storage is the fallback for a
// plain visit. Returns the values plus which source answered, so the page can
// say so rather than silently changing numbers under the visitor.
export function restoreBid(spec, { search = '', storage = null } = {}) {
  const fromLink = decodeBid(spec, search);
  if (Object.keys(fromLink).length > 0) return { values: fromLink, source: 'link' };
  const stored = loadBid(storage, spec);
  if (Object.keys(stored).length > 0) return { values: stored, source: 'storage' };
  return { values: {}, source: 'none' };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores head
// counts, wages, costs, or prices, and it never leaves the device — an
// installer's bid is exactly the sort of thing that must not be transmitted.
function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'bid_calculated') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  const today = new Date().toISOString().slice(0, 10);
  const current = JSON.parse(storage.getItem('mini-split-bid-usage') || '{}');
  current[event] = (current[event] || 0) + 1;
  current.last_day = today;
  storage.setItem('mini-split-bid-usage', JSON.stringify(current));
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem('mini-split-bid-usage-opt-out') === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem('mini-split-bid-usage'); } catch { /* storage is optional */ }
    try { storage.setItem('mini-split-bid-usage-opt-out', '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem('mini-split-bid-usage-opt-out'); } catch { /* storage is optional */ }
  }
}
